                decoder.pass(::omi::avro::native::Kind::Decimal);
                decoder.pass(::omi::avro::native::Kind::Decimal);
                decoder.pass(::omi::avro::native::Kind::Decimal);
                decoder.pass(::omi::avro::native::Kind::Decimal);
                return "DirectListingWithCapitalRaisePriceDiscoveryMessage";
